const { existsSync } = require('fs');
const path = require('path');
const { getParameters } = require('../environment');
const allure = require('allure-commandline');

let { portNumber, report_folder } = getParameters();
let reportFolder = report_folder || 'report';

//fs.existsSync still requires a fully resolved path.
reportFolder = path.resolve(process.cwd(), reportFolder);

//Allure commands do not work with paths containing spaces. Adding quotes works with command line but not run from a js file.
const relativeReportFolder = path.relative(process.cwd(), reportFolder);

try {
    if (existsSync(`${reportFolder}/allure-archives`)) {
        allure(['open', `${relativeReportFolder}/allure-archives`, '-p', `${portNumber}`]);
    }
} catch (err) {
    console.error(err);
    // console.log('No allure archived report found');
}
